'use strict';
// Click links generated by the real inbox inside the complete CRM application.
// Only synthetic local records and a stubbed private receiving queue are used.
const assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path'),http=require('node:http');
const {chromium}=require(process.env.PLAYWRIGHT_CORE_PATH||'C:/Users/rbaga/ion-mining-group/tools/.cache/hosting-terrain-browser/node_modules/playwright-core');
const {createServer}=require('../tools/preview-crm.cjs');
const A=require('../agent-control-model'),I=require('../crm/intake-inbox');
const requestId='REQ-12345678-1234-4234-8234-123456789012',id=I.taskId({id:requestId,briefRevision:1});
const state=A.reduce(A.initial(),{type:'task.add',payload:{id,title:'Exact synthetic intake research assignment',role:'supply',brief:'Synthetic route integration only. No native execution or outreach.'},revision:0,id:'event_synthetic_route',at:'2026-09-20T01:00:00.000Z'});
function testServer(){
 if(!process.env.CRM_TEST_SITE_ROOT)return createServer();
 const root=fs.realpathSync(process.env.CRM_TEST_SITE_ROOT);assert(fs.existsSync(path.join(root,'crm/index.html')),'Assembled CRM index must exist');
 const types={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json','.svg':'image/svg+xml','.png':'image/png','.woff2':'font/woff2','.webmanifest':'application/manifest+json'};
 return http.createServer((req,res)=>{let pathname;try{pathname=decodeURIComponent(new URL(req.url,'http://127.0.0.1').pathname);}catch(_){res.writeHead(400);res.end();return;}
  const file=path.resolve(root,'.'+pathname+(pathname.endsWith('/')?'index.html':'')),relative=path.relative(root,file);
  if(relative.startsWith('..')||path.isAbsolute(relative)||!fs.existsSync(file)||!fs.statSync(file).isFile()){res.writeHead(404);res.end();return;}
  res.writeHead(200,{'Content-Type':types[path.extname(file)]||'application/octet-stream','Cache-Control':'no-store'});fs.createReadStream(file).pipe(res);
 });
}
const server=testServer();
(async()=>{
 await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));const origin='http://127.0.0.1:'+server.address().port;let browser;
 try{
  browser=await chromium.launch({headless:true,executablePath:process.env.CHROME_PATH||'C:/Program Files/Google/Chrome/Application/chrome.exe'});
  const context=await browser.newContext({viewport:{width:1280,height:900},serviceWorkers:'block'});
  await context.route('**/*',r=>r.request().url().startsWith(origin)?r.continue():r.abort());
  await context.addInitScript(value=>{localStorage.setItem('protonAgentControlLocal_v1',JSON.stringify(value));},state);
  const page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));page.setDefaultTimeout(12000);
  for(const queueState of ['draft_saved','acknowledged']){
   await page.goto(origin+'/crm/#requests');await page.getByRole('heading',{name:'Requests.',exact:true}).waitFor();
   const record={id:requestId,revision:queueState==='draft_saved'?3:4,briefRevision:1,service:'custom_search',status:'qualified',receivedAt:'2026-09-20T01:00:00.000Z',routeEmail:'energy@protonminingco.com',notification:{status:'not_configured'},queue:{state:queueState,taskId:id,briefId:requestId,taskOwnerUid:'synthetic-route-owner',...(queueState==='acknowledged'?{acknowledgedBy:'Synthetic receiver',acknowledgedAt:'2026-09-20T01:30:00.000Z',evidence:'Synthetic route test only'}:{})},payload:{service:'custom_search',contact:{name:'Synthetic test customer',email:'synthetic@example.test'},brief:{country:'US',geography:'Pennsylvania',power:{value:160,unit:'kW'}},consent:true},history:[]};
   await page.evaluate(({record,register})=>{
    const D={status:()=>({uid:'synthetic-route-owner',epoch:1,ready:true,error:'',agent:{mode:'cloud'}}),snapshot:()=>({uid:'synthetic-route-owner',epoch:1,raw:[]}),agent:()=>register,sites:()=>[],subscribe(){}};
    const fetch=async url=>({ok:true,status:200,json:async()=>url.endsWith('/metrics')?{receivedTotal:1,qualifiedTotal:1,queueDrafts:record.queue.state==='draft_saved'?1:0,acknowledged:record.queue.state==='acknowledged'?1:0}:url.includes('?limit=')?{requests:[record],nextCursor:null}:{request:record}});
    const inbox=ProtonCrmIntakeInbox.create({D,model:ProtonSourcingModel,auth:{currentUser:{uid:'synthetic-route-owner',getIdToken:async()=> 'synthetic-only'}},config:{endpoint:'https://synthetic.invalid'},fetch});
    const host=document.getElementById('content');host.innerHTML=inbox.html();inbox.select(record);inbox.mount(host);
   },{record,register:state});
   const link=page.locator('.intake-detail a').filter({hasText:id});await link.waitFor();assert.equal(await link.getAttribute('href'),'#team/task/'+id,queueState+' uses supported CRM route');
   await link.click();await page.waitForFunction(()=>document.getElementById('sheet').open);assert.equal(await page.locator('#sheetTitle').innerText(),'Team assignment');assert.match(await page.locator('#sheetBody').innerText(),/Exact synthetic intake research assignment/);assert.equal(new URL(page.url()).hash,'#team/task/'+id);
   await page.reload();await page.waitForFunction(()=>document.getElementById('sheet').open);assert.match(await page.locator('#sheetBody').innerText(),/Exact synthetic intake research assignment/);assert.deepEqual(await page.evaluate(()=>JSON.parse(localStorage.getItem('protonAgentControlLocal_v1'))),state);
  }
  assert.deepEqual(errors,[]);console.log('PASS inbox draft-saved and acknowledged task links open and reload the exact task through the actual CRM router; stored records unchanged.');
 }finally{if(browser)await browser.close();await new Promise(resolve=>server.close(resolve));}
})().catch(e=>{console.error(e);process.exitCode=1;});
